253	
254	// 将物理按键 ID 映射为导航类型
255	static NavigationType map_button_to_navigation(int button_id)
256	{
257	    switch (button_id) {
258	        case BUTTON_KEY_BACK:
259	            return NAVIGATION_TYPE_LEFT;
260	        case BUTTON_KEY_HOME:
261	            return NAVIGATION_TYPE_HOME;
262	        case BUTTON_KEY_MENU:
263	            return NAVIGATION_TYPE_RIGHT;
264	        default:
265	            return NAVIGATION_TYPE_LEFT;  // 默认值
266	    }
267	}
268	
269	// 按键轮询回调
270	static void button_poll_callback(uv_poll_t* handle, int status, int events)
271	{
272	    if (status < 0) {
273	        FEATURE_LOG_ERROR("%s: Poll error: %d\n", file_tag, status);
274	        return;
275	    }
276	    
277	    if (!(events & UV_READABLE)) {
278	        return;
279	    }
280	    
281	    auto* nav_ctx = static_cast<NavigationContext*>(handle->data);
282	    if (!nav_ctx || !nav_ctx->subscribed) {
283	        return;
284	    }
285	    
286	#ifdef CONFIG_INPUT_BUTTONS
287	    struct button_notify_s btn_data;
288	    ssize_t bytes_read = read(nav_ctx->button_fd, &btn_data, sizeof(btn_data));
289	    
290	    if (bytes_read != sizeof(btn_data)) {
291	        if (bytes_read < 0 && errno != EAGAIN) {
292	            FEATURE_LOG_ERROR("%s: Read error: %d\n", file_tag, errno);
293	        }
294	        return;
295	    }
296	    
297	    // 映射为导航事件
298	    NavigationType nav_type = map_button_to_navigation(btn_data.btn_id);
299

300	    // 创建事件对象
301	    system_board_navigation_NavigationEvent* event = 
302	        system_board_navigationMallocNavigationEvent();
303	    
304	    if (!event) {
305	        FEATURE_LOG_ERROR("%s: Failed to allocate event\n", file_tag);
306	        return;
307	    }
308	    
309	    event->type = nav_type;
310	    event->timestamp = (long)time(NULL) * 1000;
311	    event->longPress = false;
312	    event->duration = 0;
313	    
314	    // 长按检测
315	    if (nav_ctx->long_press_enabled) {
316	        if (btn_data.action == BUTTON_PRESS) {
317	            gettimeofday(&nav_ctx->last_press_time, NULL);
318	            nav_ctx->last_button = btn_data.btn_id;
319	        } else if (btn_data.action == BUTTON_RELEASE) {
320	            struct timeval now;
321	            gettimeofday(&now, NULL);
322	            
323	            long duration_ms = 
324	                (now.tv_sec - nav_ctx->last_press_time.tv_sec) * 1000 +
325	                (now.tv_usec - nav_ctx->last_press_time.tv_usec) / 1000;
326	            
327	            if (duration_ms >= nav_ctx->long_press_threshold) {
328	                event->longPress = true;
329	                event->duration = duration_ms;
330	            }
331	        }
332	    }
333	    
334	    // 触发回调
335	    if (nav_ctx->navigate_callback_id != 0) {
336	        FeatureInvokeCallback(nav_ctx->handle, 
337	                            nav_ctx->navigate_callback_id, 
338	                            event);
339	    }
340	    
341	    FeatureFreeValue(event);
342	#endif
343	}
