/**
 * Navigation Feature 服务
 * 封装 system.board.navigation，提供页面导航功能
 */

import router from "@system.router"

// 页面配置（按顶栏顺序）
const PAGES = [
  { name: "首页", uri: "/pages/index" },
  { name: "新闻", uri: "/pages/news" },
  { name: "天气", uri: "/pages/weather" },
  { name: "快递", uri: "/pages/express" }
]

// 当前页面索引（从 URL 解析）
function getCurrentPageIndex() {
  const pages = getCurrentPages()
  if (pages && pages.length > 0) {
    const currentPage = pages[pages.length - 1]
    const currentPath = currentPage.route || ""

    for (let i = 0; i < PAGES.length; i++) {
      if (currentPath.includes(PAGES[i].uri.replace("/", ""))) {
        return i
      }
    }
  }
  return 0
}

// 导航到指定页面
function navigateToPage(index) {
  if (index >= 0 && index < PAGES.length) {
    router.push({ uri: PAGES[index].uri })
  }
}

// 向左导航（上一页）
function navigateLeft() {
  const currentIndex = getCurrentPageIndex()
  if (currentIndex > 0) {
    navigateToPage(currentIndex - 1)
  }
}

// 向右导航（下一页）
function navigateRight() {
  const currentIndex = getCurrentPageIndex()
  if (currentIndex < PAGES.length - 1) {
    navigateToPage(currentIndex + 1)
  }
}

// 回到首页
function navigateHome() {
  navigateToPage(0)
}

// 订阅导航事件
function subscribeNavigation() {
  try {
    const navigation = require("@system.board.navigation")

    navigation.subscribe({
      onNavigate: function(event) {
        console.log("[Navigation] 按键事件:", event.type, "长按:", event.longPress)

        switch (event.type) {
          case 0:  // LEFT - 向左
            navigateLeft()
            break
          case 1:  // HOME - 回首页
            navigateHome()
            break
          case 2:  // RIGHT - 向右
            navigateRight()
            break
        }
      },
      onError: function(message, code) {
        console.error("[Navigation] 错误:", message, code)
      },
      enableLongPress: false  // 禁用长按，只响应短按
    })

    console.log("[Navigation] 订阅成功")
    return true
  } catch (e) {
    console.log("[Navigation] Feature 不可用:", e.message)
    return false
  }
}

// 取消订阅
function unsubscribeNavigation() {
  try {
    const navigation = require("@system.board.navigation")
    navigation.unsubscribe()
    console.log("[Navigation] 取消订阅")
  } catch (e) {
    // 忽略错误
  }
}

export default {
  PAGES,
  getCurrentPageIndex,
  navigateToPage,
  navigateLeft,
  navigateRight,
  navigateHome,
  subscribeNavigation,
  unsubscribeNavigation
}

