    if (!nav_ctx || !nav_ctx->subscribed) {
        return;
    }

#ifdef CONFIG_INPUT_BUTTONS
    struct button_notify_s btn_data;
    ssize_t bytes_read = read(nav_ctx->button_fd, &btn_data, sizeof(btn_data));

    if (bytes_read != sizeof(btn_data)) {
        if (bytes_read < 0 && errno != EAGAIN) {
            FEATURE_LOG_ERROR("%s: Read error: %d\n", file_tag, errno);
        }
        return;
    }

    FEATURE_LOG_DEBUG("%s: Button %d action %d\n",
                      file_tag, btn_data.btn_id, btn_data.action);

    /* Map to navigation event */

    int nav_type = map_button_to_navigation(btn_data.btn_id);

    /* Create event object */

    system_board_navigation_NavigationEvent* event =
        system_board_navigationMallocNavigationEvent();

    if (!event) {
        FEATURE_LOG_ERROR("%s: Failed to allocate event\n", file_tag);
        return;
    }

    event->type = nav_type;
    event->timestamp = (long)time(NULL) * 1000;
    event->longPress = false;
    event->duration = 0;

    /* Long press detection */

    if (nav_ctx->long_press_enabled) {
        if (btn_data.action == BUTTON_PRESS) {
            gettimeofday(&nav_ctx->last_press_time, NULL);
            nav_ctx->last_button = btn_data.btn_id;
        } else if (btn_data.action == BUTTON_RELEASE) {
            struct timeval now;
            gettimeofday(&now, NULL);

            long duration_ms =
                (now.tv_sec - nav_ctx->last_press_time.tv_sec) * 1000 +
                (now.tv_usec - nav_ctx->last_press_time.tv_usec) / 1000;

            if (duration_ms >= nav_ctx->long_press_threshold) {
                event->longPress = true;
                event->duration = duration_ms;
            }
        }
    }

    /* Invoke callback */

    if (nav_ctx->navigate_callback_id != 0) {
        FeatureInvokeCallback(nav_ctx->handle,
                            nav_ctx->navigate_callback_id,
                            event);
    }

    FeatureFreeValue(event);
#endif
}

