static void button_poll_callback(uv_poll_t* handle, int status, int events)
{
    if (status < 0) {
        FEATURE_LOG_ERROR("%s: Poll error: %d\n", file_tag, status);
        return;
    }

    if (!(events & UV_READABLE)) {
        return;
    }

    auto* nav_ctx = static_cast<NavigationContext*>(handle->data);
    if (!nav_ctx || !nav_ctx->subscribed) {
        return;
    }

    /* Read button state from device */

    btn_buttonset_t button_state;
    ssize_t bytes_read = read(nav_ctx->button_fd, &button_state, sizeof(button_state));

    if (bytes_read != sizeof(button_state)) {
        if (bytes_read < 0 && errno != EAGAIN) {
            FEATURE_LOG_ERROR("%s: Read error: %d\n", file_tag, errno);
        }
        return;
    }

    FEATURE_LOG_DEBUG("%s: Button state: 0x%08x\n", file_tag, button_state);

    /* Check which button was pressed */

    int nav_type = -1;
    if (button_state & BUTTON_KEY_BACK_BIT) {
        nav_type = NAVIGATION_TYPE_LEFT;
    } else if (button_state & BUTTON_KEY_HOME_BIT) {
        nav_type = NAVIGATION_TYPE_HOME;
    } else if (button_state & BUTTON_KEY_MENU_BIT) {
        nav_type = NAVIGATION_TYPE_RIGHT;
    }

    if (nav_type < 0) {
        return;  /* No recognized button pressed */
    }

    /* Create event object */

    system_board_navigation_NavigationEvent* event =
        system_board_navigationMallocNavigationEvent();

    if (!event) {
        FEATURE_LOG_ERROR("%s: Failed to allocate event\n", file_tag);
        return;
    }

    event->type = nav_type;
    event->timestamp = (long)time(NULL) * 1000;
    event->longPress = false;
    event->duration = 0;

    /* Invoke callback */

    if (nav_ctx->navigate_callback_id != 0) {
        FeatureInvokeCallback(nav_ctx->handle,
                            nav_ctx->navigate_callback_id,
                            event);
    }

    FeatureFreeValue(event);
}

