155	static void lradc_irq_callback(uint32_t irq_status, uint32_t data)
156	{
157		uint32_t notify_data = 0;
158		if (HW_VERSION_DVT3 == g_hw_version) { //DVT3
159			if(data>=32 && data<=36)
160				notify_data = BUTTON_4;
161			else if(data>=40 && data<=44)
162				notify_data = BUTTON_5;
163			else if(data>=24 && data<=28)
164				notify_data = BUTTON_3;
165			else if(data>=16 && data<=20)
166				notify_data = BUTTON_2;
167			else if(data>=8 && data<=12)
168				notify_data = BUTTON_1;
169		} else { //DVT1 DVT2
170			if(data>=8 && data<=12)
171				notify_data = BUTTON_1;
172			else if(data>=17 && data<=21)
173				notify_data = BUTTON_2;
174			else if(data>=25 && data<=29)
175				notify_data = BUTTON_3;
176			else if(data>=33 && data<=37)
177				notify_data = BUTTON_4;
178			else if(data>=39 && data<=43)
179				notify_data = BUTTON_5;
180		}
181		if (gLastButton != notify_data) {
182			syslog(LOG_INFO,"gLastButton=%lu,notify_data=%lu\n",gLastButton,notify_data);
183			gLastButton = notify_data;
184			if (g_btnhandler)
185				g_btnhandler(&g_btnlower,g_btnarg);
186		}
187	}
