107	static void button_poll_callback(uv_poll_t* handle, int status, int events)
108	{
109	    if (status < 0) {
110	        FEATURE_LOG_ERROR("%s: Poll error: %d\n", file_tag, status);
111	        return;
112	    }
113	
114	    if (!(events & UV_READABLE)) {
115	        return;
116	    }
117	
118	    auto* nav_ctx = static_cast<NavigationContext*>(handle->data);
119	    if (!nav_ctx || !nav_ctx->subscribed) {
120	        return;
121	    }
122	
123	    /* Read button state from device */
124	
125	    btn_buttonset_t button_state;
126	    ssize_t bytes_read = read(nav_ctx->button_fd, &button_state, sizeof(button_state));
127	
128	    if (bytes_read != sizeof(button_state)) {
129	        if (bytes_read < 0 && errno != EAGAIN) {
130	            FEATURE_LOG_ERROR("%s: Read error: %d\n", file_tag, errno);
131	        }
132	        return;
133	    }
134	
135	    FEATURE_LOG_DEBUG("%s: Button state: 0x%08x\n", file_tag, button_state);
136	
137	    /* Check which button was pressed */
138	
139	    int nav_type = -1;
140	    if (button_state & BUTTON_KEY_BACK_BIT) {
141	        nav_type = NAVIGATION_TYPE_LEFT;
142	    } else if (button_state & BUTTON_KEY_HOME_BIT) {
143	        nav_type = NAVIGATION_TYPE_HOME;
144	    } else if (button_state & BUTTON_KEY_MENU_BIT) {
145	        nav_type = NAVIGATION_TYPE_RIGHT;
146	    }
147	
148	    if (nav_type < 0) {
149	        return;  /* No recognized button pressed */
150	    }
151	
152	    /* Create event object */
153	
154	    system_board_navigation_NavigationEvent* event =
155	        system_board_navigationMallocNavigationEvent();
156	
157	    if (!event) {
158	        FEATURE_LOG_ERROR("%s: Failed to allocate event\n", file_tag);
159	        return;
160	    }
161	
162	    event->type = nav_type;
163	    event->timestamp = (long)time(NULL) * 1000;
164	    event->longPress = false;
165	    event->duration = 0;
166	
167	    /* Invoke callback */
168	
169	    if (nav_ctx->navigate_callback_id != 0) {
170	        FeatureInvokeCallback(nav_ctx->handle,
171	                            nav_ctx->navigate_callback_id,
172	                            event);
173	    }
174	
175	    FeatureFreeValue(event);
176	}
