// GPIO pin definitions (from board.h)
#define GPIO_KEY_BACK   17  /* PH17 */
#define GPIO_KEY_HOME   18  /* PH18 */
#define GPIO_KEY_MENU   19  /* PH19 */

#define BUTTONS_DEVICE_PATH "/dev/buttons0"

#define NAVIGATION_TYPE_LEFT   0
#define NAVIGATION_TYPE_HOME   1
#define NAVIGATION_TYPE_RIGHT  2

#define BUTTON_KEY_BACK_BIT  (1 << GPIO_KEY_BACK)
#define BUTTON_KEY_HOME_BIT  (1 << GPIO_KEY_HOME)
#define BUTTON_KEY_MENU_BIT  (1 << GPIO_KEY_MENU)

struct NavigationContext {
    uv_loop_t* loop;
    uv_poll_t button_poller;
    int button_fd;
    FtCallbackId navigate_callback_id;
    FtCallbackId error_callback_id;
    FeatureInstanceHandle handle;
    bool long_press_enabled;
    int long_press_threshold;
    struct timeval last_press_time;
    int last_button;
    bool subscribed;
};

// Feature 生命周期回调
void system_board_navigation_onRegister(const char* feature_name);
void system_board_navigation_onCreate(FeatureRuntimeContext ctx, FeatureProtoHandle handle);
void system_board_navigation_onRequired(FeatureRuntimeContext ctx, FeatureInstanceHandle handle);
void system_board_navigation_onDetached(FeatureRuntimeContext ctx, FeatureInstanceHandle handle);
void system_board_navigation_onDestroy(FeatureRuntimeContext ctx, FeatureProtoHandle handle);
void system_board_navigation_onUnregister(const char* feature_name);

// Feature 方法
